namespace sv_91e836bc4cb24265a9380d465dcb5741.Services;

public sealed record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> Data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with fresh mozzarella, basil, and tomato sauce.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with pancetta, egg yolk, and pecorino cheese.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Pad Thai", "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.", 35),
            new(5, "Green Curry", "Aromatic coconut curry with chicken, bamboo shoots, and Thai basil.", 40),
            new(6, "Mango Sticky Rice", "Sweet sticky rice topped with fresh mango and coconut cream.", 50),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 60),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Churros", "Crispy fried dough coated in cinnamon sugar with chocolate sauce.", 35),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (Data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_91e836bc4cb24265a9380d465dcb5741.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <strong>Cuisine:</strong>
    <a href="/recipes/1?sort=@Sort" class="btn btn-sm @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn btn-sm @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary")">Thai</a>
    <a href="/recipes/3?sort=@Sort" class="btn btn-sm @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Mexican</a>
</div>

<div class="mb-3">
    <strong>Sort:</strong>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "newest" ? "btn-secondary" : "btn-outline-secondary")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <p><em>Loading recipes...</em></p>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block mb-2" role="status">
            Refreshing…
        </div>
    }

    <div class="row">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <span class="badge bg-info">@recipe.PrepTimeMinutes min</span>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!_recipes.Any())
    {
        <p>No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        Sort ??= "newest";

        // Only reload when cuisine changes, not when sort changes.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request.
        await CancelPendingRequestAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale callback after cancellation.
            if (cts.Token.IsCancellationRequested) return;

            _recipes = result;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException)
        {
            // Request was intentionally cancelled — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return Enumerable.Empty<Recipe>();

        return Sort?.ToLowerInvariant() switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
            _ => _recipes.OrderByDescending(r => r.Id),
        };
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

