@using sv_91e836bc4cb24265a9380d465dcb5741.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <strong>Cuisine:</strong>
    <a href="/recipes/1?sort=@Sort" class="btn btn-sm @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn btn-sm @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary")">Thai</a>
    <a href="/recipes/3?sort=@Sort" class="btn btn-sm @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Mexican</a>
</div>

<div class="mb-3">
    <strong>Sort:</strong>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "newest" ? "btn-secondary" : "btn-outline-secondary")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

